import Dropdown from 'flarum/common/components/Dropdown';
import Button from 'flarum/common/components/Button';
import { moderate, t, tx } from '../util';
import { openShare } from '../share';

/** The ⋯ menu on a card: what this viewer may do to it (feature, order, edit, decline, take down). */
function ControlsView(attrs) {
  const row = attrs.row;
  const done = () => attrs.onchange?.();
  const items = [];
  if (row.canModerate()) {
    if (row.status() === 'approved') {
      items.push(row.isFeatured() ? m(Button, {
        icon: "far fa-star",
        onclick: () => moderate(row, 'unfeature').then(done)
      }, t('controls.unfeature')) : m(Button, {
        icon: "fas fa-star",
        onclick: () => moderate(row, 'feature').then(done)
      }, t('controls.feature')));
      if (row.isFeatured()) {
        items.push(m(Button, {
          icon: "fas fa-arrow-up",
          onclick: () => moderate(row, 'up').then(done)
        }, t('controls.move_up')), m(Button, {
          icon: "fas fa-arrow-down",
          onclick: () => moderate(row, 'down').then(done)
        }, t('controls.move_down')));
      }
    }
  }
  if (row.canEdit() || row.canEditWording()) {
    items.push(m(Button, {
      icon: "fas fa-pen",
      onclick: () => openShare({
        testimonial: row
      })
    }, row.canEdit() ? t('controls.edit') : t('controls.edit_wording')));
  }
  if (row.canHide()) {
    items.push(m(Button, {
      icon: row.hiddenByAuthor() ? 'fas fa-eye' : 'fas fa-eye-slash',
      onclick: () => row.save({
        hiddenByAuthor: !row.hiddenByAuthor()
      }).then(() => {
        done();
        m.redraw();
      })
    }, row.hiddenByAuthor() ? t('controls.show_depot') : t('controls.hide_depot')));
  }
  if (row.canModerate() && row.status() !== 'declined' && row.status() !== 'removed') {
    items.push(m(Button, {
      icon: "fas fa-xmark",
      onclick: () => {
        const reason = window.prompt(tx('controls.decline_prompt'));
        if (reason !== null) moderate(row, 'decline', {
          reason
        }).then(done);
      }
    }, t('controls.decline')));
  }
  if (row.canRemove()) {
    items.push(m(Button, {
      icon: "fas fa-trash-can",
      onclick: () => {
        if (window.confirm(tx('controls.remove_confirm'))) moderate(row, 'remove').then(done);
      }
    }, t('controls.remove')));
  }
  if (row.canRestore()) {
    items.push(m(Button, {
      icon: "fas fa-rotate-left",
      onclick: () => moderate(row, 'restore').then(done)
    }, t('controls.restore')));
  }
  if (!items.length) return null;
  return m(Dropdown, {
    className: "TestimonialControls",
    buttonClassName: "Button Button--icon Button--flat",
    menuClassName: "Dropdown-menu--right",
    icon: "fas fa-ellipsis-h",
    label: tx('controls.label'),
    accessibleToggleLabel: tx('controls.label')
  }, items);
}
const Controls = {
  view: vnode => ControlsView(vnode.attrs)
};
export default Controls;
flarum.reg.add('ernestdefoe-testimonials', 'forum/components/Controls', Controls);